// Parse Teams — exploite le contenu intrinsèque du message
const payload = $input.first().json;
let m = {};

// Essaye plusieurs sources pour le message
if (typeof payload.body?.message === 'string') {
  m = JSON.parse(payload.body.message);
} else if (typeof payload.message === 'string') {
  m = JSON.parse(payload.message);
} else if (payload.from?.user) {
  m = payload; // déjà parsé (message Graph API brut)
}

// Détection des @mentions et type de conversation
const wylliamId = '9f956725-164d-4c39-a211-74fea544bf4e';
const chatId = m.chatId || payload.body?.conversationId || payload.chatId || '';
const mentions = Array.isArray(m.mentions) ? m.mentions : [];
const isMentioned = mentions.some(men =>
  men.mentioned?.user?.id === wylliamId ||
  (men.mentionText && men.mentionText.toLowerCase().includes('wylliam'))
);
// 1:1 chat = contient "_UUID@", groupe = @thread.v2
const isDirectMessage = /_[a-f0-9-]{20,}@/.test(chatId);

// Utilise les champs intrinsèques du payload Power Automate comme fallback
const result = {
  senderName: m.from?.user?.displayName || m.from?.displayName || payload.senderName || 'Inconnu',
  senderId: m.from?.user?.id || m.from?.id || payload.senderId || '',
  messageText: (m.body?.plainTextContent || payload.body?.messageText || m.text || '').replace(/<[^>]*>/g, ''),
  messageLink: payload.body?.lien || payload.lien || m.messageLink || '',
  chatId: chatId,
  isFromWylliam: (m.from?.user?.id || payload.senderId) === wylliamId,
  isMentioned: isMentioned,
  isDirectMessage: isDirectMessage
};

// Debug log via console
console.log('[ParseTeams]', JSON.stringify({
  sender: result.senderName,
  mentioned: isMentioned,
  direct: isDirectMessage,
  chatId: chatId.substring(0, 30)
}));

return result;

const chatId = $input.first().json.chatId;
if (!chatId) return { exists: false, chatId: '' };

const res = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.notion.com/v1/databases/38c15cc8-89a0-81b3-9890-cee60d8a9ab0/query',
  headers: {
    'Authorization': 'Bearer PLACEHOLDER_NOTION_TOKEN_SOPS',
    'Notion-Version': '2022-06-28'
  },
  body: {
    filter: { property: 'Conversation ID', rich_text: { equals: chatId } },
    page_size: 1
  }
});

const page = res.results?.[0];
if (page) {
  const p = page.properties;
  return { exists:true, pageId:page.id, chatId,
    oldResume:p['Résumé']?.rich_text?.[0]?.plain_text||'',
    oldSujet:p['Sujet']?.title?.[0]?.plain_text||'',
    oldStatus:p['Statut']?.select?.name||'🟡 En cours'
  };
}
return { exists:false, chatId };

const {oldResume,oldSujet,pageId,chatId,oldStatus} = $input.first().json;
const msg = $('Parse Teams').first().json;
return {
  _mode:'append', pageId, chatId, oldResume, oldSujet,
  newMsg:'['+msg.senderName+']: '+msg.messageText,
  lastInterv:msg.isFromWylliam?'Wylliam':'Autre', oldStatus,
  senderName:msg.senderName, messageLink:msg.messageLink,
  isMentioned:msg.isMentioned, isDirectMessage:msg.isDirectMessage,
  isDirectlyAddressed:(msg.isMentioned||msg.isDirectMessage)?'Oui':'Non'
};

const msg=$('Parse Teams').first().json;
return {
  _mode:'new', chatId:msg.chatId, messageLink:msg.messageLink,
  senderName:msg.senderName, messageText:msg.messageText,
  lastInterv:'Autre',
  isMentioned:msg.isMentioned, isDirectMessage:msg.isDirectMessage,
  isDirectlyAddressed:(msg.isMentioned||msg.isDirectMessage)?'Oui':'Non'
};

const llm = $input.first().json;
const ap = $('Format append').first().json;
const actions = Array.isArray(llm.actions) ? llm.actions.join('\n') : '';
let resume = actions;
if (llm.dernier_msg) resume += '\n💬 '+llm.dernier_msg;
const sujet = llm.sujet||ap.oldSujet||'Action Teams';

await this.helpers.httpRequest({
  method: 'PATCH',
  url: 'https://api.notion.com/v1/pages/'+ap.pageId,
  headers: {'Authorization':'Bearer PLACEHOLDER_NOTION_TOKEN_SOPS','Notion-Version':'2022-06-28'},
  body: {properties:{
    'Sujet':{title:[{text:{content:sujet.substring(0,100)}}]},
    'Résumé':{rich_text:[{text:{content:resume.substring(0,1900)}}]},
    'Dernier intervenant':{select:{name:ap.lastInterv}},
    'Dernière activité':{date:{start:new Date().toISOString()}},
    'Statut':{select:{name:(ap.lastInterv==='Wylliam' && ap.oldStatus==='🔴 À promouvoir')?'✅ Clos':'🟡 En cours'}},
            'Ne pas promouvoir':{checkbox:ap.isDirectlyAddressed==='Non'}
  }}
});
return {action:'updated',chatId:ap.chatId,sujet};

const llm = $input.first().json;
const fn = $('Format new').first().json;
const action = (llm.action||'').trim();
const sujet = llm.sujet||llm.titre_action||'Action Teams';
const contexte = llm.contexte||'';
const confiance = llm.confiance||'À vérifier';
const isActionable = action==='Faire' || action==='Planifier' || action==='Déléguer';

// 1. TOUJOURS créer l'entrée dans Teams En Cours (pour suivi/auto-closure)
await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.notion.com/v1/pages',
  headers: {'Authorization':'Bearer PLACEHOLDER_NOTION_TOKEN_SOPS','Notion-Version':'2022-06-28'},
  body: {parent:{database_id:'38c15cc8-89a0-81b3-9890-cee60d8a9ab0'},properties:{
    'Sujet':{title:[{text:{content:sujet.substring(0,100)}}]},
    'Conversation ID':{rich_text:[{text:{content:fn.chatId||'n/a'}}]},
    'Résumé':{rich_text:[{text:{content:(sujet+': '+contexte).substring(0,500)}}]},
    'Lien Teams':{url:fn.messageLink||null},
    'Statut':{select:{name:isActionable?'🔴 À promouvoir':'🟡 En cours'}},
    'Dernier intervenant':{select:{name:fn.senderName||'Autre'}},
    'Dernière activité':{date:{start:new Date().toISOString()}},
    'Ne pas promouvoir':{checkbox:fn.isDirectlyAddressed==='Non'}
  }}
});

// 2. Si action Faire/Planifier/Déléguer → créer aussi dans Inbox GTD
if (isActionable) {
  const actionEmoji = action==='Faire'?'➡️':(action==='Planifier'?'📅':'👤');
  await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.notion.com/v1/pages',
    headers: {'Authorization':'Bearer PLACEHOLDER_NOTION_TOKEN_SOPS','Notion-Version':'2022-06-28'},
    body: {parent:{database_id:'6b279b50-1f54-4b57-b96d-919c5f667730'},properties:{
      'Capture':{title:[{text:{content:(actionEmoji+' '+sujet).substring(0,100)}}]},
      'Action':{select:{name:actionEmoji+' '+action}},
      'Confiance':{select:{name:confiance.includes('Certain')?'✅ Certain':'🟡 À vérifier'}},
      'Notes':{rich_text:[{text:{content:contexte.substring(0,500)}}]},
      'Lien Source':{url:fn.messageLink||null},
      'Source':{select:{name:'💬 Teams'}},
      'Traité':{checkbox:false}
    }}
  });
}

return {action:(isActionable?'promoted':'logged'),chatId:fn.chatId,sujet};

// Parse LLM Output — extrait le JSON de la réponse textuelle du LLM
const raw = $input.first().json;
const text = raw.text || raw.output || '';

// Stratégie 1: extraire le JSON depuis un bloc markdown ```json ... ```
let jsonStr = text;
const blockMatch = text.match(/```(?:json)?\s*\n?([\s\S]*?)```/);
if (blockMatch) {
  jsonStr = blockMatch[1].trim();
}

// Stratégie 2: trouver le premier objet JSON valide dans le texte
let parsed = {};
try {
  parsed = JSON.parse(jsonStr);
} catch (e) {
  const depth = (s) => { let d=0; for(let c of s){if(c==='{')d++;if(c==='}')d--;if(d<0)return -1} return d; };
  for (let i = 0; i < text.length; i++) {
    if (text[i] === '{') {
      for (let j = i+1; j <= text.length; j++) {
        if (depth(text.substring(i, j)) === 0) {
          try {
            parsed = JSON.parse(text.substring(i, j));
            break;
          } catch (e2) {}
        }
      }
      if (parsed.action) break;
    }
  }
}

// Fusionne les champs passthrough + LLM parsé
return {
  ...raw,              // _mode, chatId, senderName, etc. (grâce au passthrough activé)
  ...parsed,           // action, sujet, contexte, confiance, actions[], dernier_msg, titre_action
  _llmRaw: text        // garde le raw pour debug
};
